  { id: 'bn027', category: 'business', difficulty: 'normal', question: "What is a service-level agreement (SLA)?", options: ["A document listing a company's brand colours","A plan for launching a new product","An agreement defining expected service standards and responsibilities","A list of employees eligible for bonuses"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.ibm.com/think/topics/service-level-agreement' },
  { id: 'bn028', category: 'business', difficulty: 'normal', question: "What is a key purpose of supply-chain management?", options: ["Designing advertisements for retail customers","Setting employee annual leave allowances","Registering patents for new products","Coordinating the flow of goods, information and activities from suppliers to customers"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.ibm.com/think/topics/supply-chain-management' },
  { id: 'bn029', category: 'business', difficulty: 'normal', question: "What is just-in-time (JIT) inventory management intended to do?", options: ["Receive or produce goods close to when they are needed, reducing excess stock","Keep the maximum possible stock at all times","Eliminate the need to forecast demand","Require every product to be made only after payment"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/j/jit.asp' },
  { id: 'bn030', category: 'business', difficulty: 'normal', question: "What is a reorder point in inventory management?", options: ["The date a product's trademark expires","The stock level at which replenishment should be triggered","The price at which a supplier must sell goods","The number of customers served in one hour"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/r/reorder-point.asp' },
  { id: 'bn031', category: 'business', difficulty: 'normal', question: "What does inventory turnover measure?", options: ["The number of warehouses a company owns","The percentage of products that are advertised","How often inventory is sold and replaced over a period","The average time employees spend at work"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/i/inventoryturnover.asp' },
  { id: 'bn032', category: 'business', difficulty: 'normal', question: "What is economies of scale?", options: ["A tax reduction given to every new business","A method of pricing based only on competitors","A system for measuring customer satisfaction","Lower average costs that can result as production volume increases"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.britannica.com/money/economies-of-scale' },
  { id: 'bn033', category: 'business', difficulty: 'normal', question: "What is a franchise royalty commonly paid for?", options: ["Ongoing use of a franchisor's brand, system or support under the agreement","A refund for unsold products","The registration of an employee's professional qualification","A one-time purchase of office furniture"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.sba.gov/business-guide/plan-your-business/buy-existing-business-or-franchise' },
  { id: 'bn034', category: 'business', difficulty: 'normal', question: "What is due diligence before acquiring a business?", options: ["A public launch event for the new owner","A careful investigation of relevant financial, legal and operational information","A discount offered to the seller's customers","A routine stock count performed after closing"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/d/duediligence.asp' },
  { id: 'bn035', category: 'business', difficulty: 'normal', question: "What is a merger?", options: ["A short-term agreement to share advertising costs","A business's annual financial audit","The combination of two or more businesses into one organisation or group","The closure of a company's least profitable shop"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/m/merger.asp' },
  { id: 'bn036', category: 'business', difficulty: 'normal', question: "What is an acquisition in business?", options: ["A reduction in the price of a product","The transfer of a customer from one sales team to another","A company's decision to stop manufacturing a product","One company purchasing control of another business or its assets"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/a/acquisition.asp' },
  { id: 'bn037', category: 'business', difficulty: 'normal', question: "What is equity financing?", options: ["Raising capital by selling an ownership interest in a business","Borrowing money that must be repaid with interest","Reducing the number of products held in stock","Delaying payment to a supplier"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/e/equityfinancing.asp' },
  { id: 'bn038', category: 'business', difficulty: 'normal', question: "What is debt financing?", options: ["Selling part of the company to new shareholders","Raising money by borrowing, with an obligation to repay","Receiving a customer refund","Converting inventory into fixed assets"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/d/debtfinancing.asp' },
  { id: 'bn039', category: 'business', difficulty: 'normal', question: "What is dilution in startup equity financing?", options: ["An increase in the company's product prices","A reduction in the company's operating expenses","A decrease in an existing owner's percentage ownership after new shares are issued","A decrease in the number of customers served"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/d/dilution.asp' },
  { id: 'bn040', category: 'business', difficulty: 'normal', question: "What does a term sheet typically outline in an investment deal?", options: ["The company's daily social-media posting schedule","A detailed list of all customer complaints","The final audited accounts for every prior year","Key proposed terms and conditions of the investment"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/t/termsheet.asp' },
  { id: 'bn041', category: 'business', difficulty: 'normal', question: "What is an initial public offering (IPO)?", options: ["The first sale of a company's shares to the public on a stock market","A company's first sale to a wholesale customer","A private loan from a bank","A government grant for a new business"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/i/ipo.asp' },
  { id: 'bn042', category: 'business', difficulty: 'normal', question: "What is an audit in business accounting?", options: ["A marketing survey of existing customers","An independent examination of financial records or controls","A count of products on a retail shelf only","A negotiation between a business and its landlord"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/a/audit.asp' },
  { id: 'bn043', category: 'business', difficulty: 'normal', question: "What is an internal control in an organisation?", options: ["A social-media guideline for staff","A discount policy for returning customers","A process or procedure designed to help manage risk and support reliable operations","A list of products that have been discontinued"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.coso.org/Pages/ic.aspx' },
  { id: 'bn044', category: 'business', difficulty: 'normal', question: "What is the purpose of a procurement process?", options: ["Create a company's annual advertising slogan","Calculate the depreciation of machinery","Measure the satisfaction of retail customers","Acquire goods or services under defined requirements and controls"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.cips.org/intelligence-hub/procurement/what-is-procurement' },
  { id: 'bn045', category: 'business', difficulty: 'normal', question: "What does net working capital help indicate?", options: ["A business's short-term liquidity position","The total market share of a brand","The number of new product launches","The average salary of company directors"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/n/networkingcapital.asp' },
  { id: 'bn046', category: 'business', difficulty: 'normal', question: "What is contribution margin per unit?", options: ["The total revenue divided by total assets","Selling price per unit minus variable cost per unit","Fixed costs divided by number of employees","Net income before interest and tax"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/c/contributionmargin.asp' },

  // Business — Hard grade, curated batch.
  { id: 'bh001', category: 'business', difficulty: 'hard', question: "What is EBITDA commonly used to assess?", options: ["A company's operating performance before interest, taxes, depreciation and amortization","The total cash paid to shareholders","The market price of a company's shares","The value of inventory after tax"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/e/ebitda.asp' },
  { id: 'bh002', category: 'business', difficulty: 'hard', question: "What does enterprise value (EV) attempt to represent?", options: ["Only the company's cash balance","The value of a business including equity and debt, adjusted for cash","The total value of its annual sales","The original cost of its physical assets"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/e/enterprisevalue.asp' },
  { id: 'bh003', category: 'business', difficulty: 'hard', question: "What is the current ratio used to evaluate?", options: ["Long-term brand awareness","The percentage of revenue spent on advertising","A company's ability to meet short-term obligations using current assets","The annual growth rate of employee headcount"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/c/currentratio.asp' },
  { id: 'bh004', category: 'business', difficulty: 'hard', question: "What does the quick ratio exclude from current assets in its common calculation?", options: ["Cash and cash equivalents","Marketable securities","Accounts receivable","Inventory and other less-liquid current assets"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/q/quickratio.asp' },
  { id: 'bh005', category: 'business', difficulty: 'hard', question: "What does the debt-to-equity ratio compare?", options: ["A company's total debt with shareholders' equity","Revenue with the cost of goods sold","Cash flow with inventory turnover","The number of lenders with the number of customers"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/d/debtequityratio.asp' },
  { id: 'bh006', category: 'business', difficulty: 'hard', question: "What is the weighted average cost of capital (WACC)?", options: ["The average selling price across all products","The blended required return on a company's sources of capital","The average wage paid to employees","The total cost of goods purchased from suppliers"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/w/wacc.asp' },
  { id: 'bh007', category: 'business', difficulty: 'hard', question: "What is discounted cash flow (DCF) valuation based on?", options: ["The current book value of office equipment only","The number of shares traded each day","The present value of expected future cash flows","The company's historical marketing expenditure"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/d/dcf.asp' },
  { id: 'bh008', category: 'business', difficulty: 'hard', question: "What does net present value (NPV) measure?", options: ["The total number of customers acquired","The amount of cash held at year-end","The time needed to recover an investment's initial cost","The present value of expected cash inflows minus the initial and other relevant outflows"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/n/npv.asp' },
  { id: 'bh009', category: 'business', difficulty: 'hard', question: "What is the internal rate of return (IRR) of an investment?", options: ["The discount rate that makes its net present value equal to zero","The annual percentage increase in staff salaries","The ratio of debt to total assets","The price at which a product breaks even"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/i/irr.asp' },
  { id: 'bh010', category: 'business', difficulty: 'hard', question: "What does the payback period measure?", options: ["The time a customer has to return a product","How long it takes for an investment's cash inflows to recover its initial cost","The time required to register a business name","The period between two annual audits"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/p/paybackperiod.asp' },
  { id: 'bh011', category: 'business', difficulty: 'hard', question: "What is operating leverage?", options: ["The ability to borrow money without collateral","The percentage of sales paid as commission","The extent to which fixed operating costs magnify the effect of sales changes on operating profit","The number of managers supervising a team"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/o/operatingleverage.asp' },
  { id: 'bh012', category: 'business', difficulty: 'hard', question: "What is contribution analysis used to understand?", options: ["The total value of a company's patents","The market share of its largest competitor","The amount of tax paid on dividends","How sales contribute toward covering fixed costs and generating profit"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/c/contributionmargin.asp' },
  { id: 'bh013', category: 'business', difficulty: 'hard', question: "What is price elasticity of demand?", options: ["How responsive quantity demanded is to a change in price","The total cost of transporting goods","The percentage of customers who renew a subscription","The rate at which inventory becomes obsolete"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/p/priceelasticity.asp' },
  { id: 'bh014', category: 'business', difficulty: 'hard', question: "What is price skimming?", options: ["Setting a price below variable cost indefinitely","Launching at a relatively high price and reducing it over time as market conditions change","Charging every customer a different tax rate","Matching the lowest competitor price in every transaction"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/p/priceskimming.asp' },
  { id: 'bh015', category: 'business', difficulty: 'hard', question: "What is penetration pricing?", options: ["Setting a premium price to signal exclusivity","Increasing prices as soon as demand rises","Using a relatively low introductory price to gain market share","Charging customers based on their income tax bracket"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/p/penetration-pricing.asp' },
  { id: 'bh016', category: 'business', difficulty: 'hard', question: "What is price discrimination in economics?", options: ["Offering one fixed price to every buyer","Selling only through wholesale distributors","Changing a product's name in different markets","Charging different prices to different customers for the same or similar product when conditions permit"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.britannica.com/money/price-discrimination' },
  { id: 'bh017', category: 'business', difficulty: 'hard', question: "What is the purpose of cohort analysis?", options: ["Compare groups of customers who share a defined characteristic or starting event over time","Calculate the depreciation of factory equipment","Estimate the exchange rate for imported goods","Measure the number of products displayed in a shop"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.amplitude.com/explore/analytics/cohort-analysis' },
  { id: 'bh018', category: 'business', difficulty: 'hard', question: "What does an A/B test compare?", options: ["Two unrelated companies' annual accounts","Two versions of an experience to see which performs better against a defined measure","The cost of two different suppliers' warehouses","A company's cash flow before and after tax only"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.optimizely.com/optimization-glossary/ab-testing/' },
  { id: 'bh019', category: 'business', difficulty: 'hard', question: "What is statistical significance in an experiment intended to assess?", options: ["Whether the winning design looks more attractive","Whether a result is commercially profitable in every market","Whether observed data provide evidence against a specified null hypothesis","Whether every participant gave the same answer"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.nist.gov/itl/sed/statistical-reference-datasets' },
  { id: 'bh020', category: 'business', difficulty: 'hard', question: "What is the purpose of a control group in a business experiment?", options: ["Receive the highest possible discount","Guarantee that every customer sees the same advert","Replace the need to define an outcome measure","Provide a comparison baseline that does not receive the tested intervention"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.nist.gov/itl/sed/statistical-reference-datasets' },
  { id: 'bh021', category: 'business', difficulty: 'hard', question: "What is brand equity?", options: ["The value associated with a brand's name and the effects of consumer perceptions and associations","The total amount of shares issued by a company","The value of a brand's office furniture","The amount of cash in a marketing department"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.ama.org/topics/branding/' },
  { id: 'bh022', category: 'business', difficulty: 'hard', question: "What is brand positioning intended to establish?", options: ["The physical location of the brand's headquarters","A distinctive place for the brand in the minds of its target audience relative to alternatives","The order in which products appear in a warehouse","The legal ownership of a company's domain name"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.ama.org/topics/branding/' },
  { id: 'bh023', category: 'business', difficulty: 'hard', question: "What does share of voice measure in marketing?", options: ["The percentage of customers who make repeat purchases","The number of employees who speak at company events","A brand's share of relevant advertising or media exposure compared with competitors","The percentage of revenue paid to distributors"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.thinkwithgoogle.com/marketing-strategies/data-and-measurement/' },
  { id: 'bh024', category: 'business', difficulty: 'hard', question: "What is incrementality in marketing measurement?", options: ["The total number of clicks recorded by a campaign","The percentage of customers who already intended to buy","The average time spent on a website","The additional outcomes caused by an activity beyond what would have happened anyway"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.thinkwithgoogle.com/marketing-strategies/data-and-measurement/' },
  { id: 'bh025', category: 'business', difficulty: 'hard', question: "What is the purpose of marketing attribution?", options: ["Assign credit to marketing touchpoints that contributed to a conversion or outcome","Determine the legal structure of a business","Calculate the depreciation of advertising equipment","Set the minimum wage for sales staff"], answer: 0, reviewedAt: '2026-11-06', source: 'https://support.google.com/analytics/answer/10596866' },
  { id: 'bh026', category: 'business', difficulty: 'hard', question: "What is a positioning map commonly used to visualise?", options: ["A company's delivery routes","How brands or products are perceived across selected attributes","The physical location of customer support offices","The number of products stored at each branch"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.ama.org/topics/marketing-strategy/' },
  { id: 'bh027', category: 'business', difficulty: 'hard', question: "What is a blue ocean strategy?", options: ["Competing only by lowering prices in a crowded market","Acquiring every direct competitor","Creating new market space where competition is less relevant","Focusing only on existing customers and products"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.blueoceanstrategy.com/what-is-blue-ocean-strategy/' },
  { id: 'bh028', category: 'business', difficulty: 'hard', question: "What is a moat in business strategy?", options: ["A temporary increase in advertising spend","A company's short-term cash balance","A list of its registered trademarks","A durable advantage that makes it difficult for competitors to erode its position"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/e/economicmoat.asp' },
  { id: 'bh029', category: 'business', difficulty: 'hard', question: "What does vertical integration involve?", options: ["Expanding control into stages of a supply chain, such as suppliers or distribution","Selling the same product in a new country only","Replacing employees with automated software","Combining two companies that sell unrelated services"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.britannica.com/money/vertical-integration' },
  { id: 'bh030', category: 'business', difficulty: 'hard', question: "What is horizontal integration?", options: ["Moving production closer to raw-material suppliers","Expanding by combining with or acquiring a business at the same stage of the value chain","Outsourcing all customer service operations","Reducing the number of products sold"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.britannica.com/money/horizontal-integration' },
  { id: 'bh031', category: 'business', difficulty: 'hard', question: "What is a go-to-market strategy?", options: ["A plan for reducing a company's historical tax liability","A method for calculating depreciation","A plan for reaching target customers and delivering a product or service to the market","A schedule for renewing office equipment"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.productplan.com/glossary/go-to-market-strategy/' },
  { id: 'bh032', category: 'business', difficulty: 'hard', question: "What is product-market fit?", options: ["A product's packaging matches the brand's colour palette","The product is available in every retail store","The product has the lowest price in its category","A product satisfies a strong market demand among a defined group of customers"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.ycombinator.com/library/5z-the-real-product-market-fit' },
  { id: 'bh033', category: 'business', difficulty: 'hard', question: "What is the purpose of a minimum viable product (MVP)?", options: ["Test key assumptions with the smallest useful version that can deliver learning from users","Launch every planned feature at once","Avoid collecting feedback until after a full-scale launch","Create a permanent replacement for market research"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.productplan.com/glossary/minimum-viable-product/' },
  { id: 'bh034', category: 'business', difficulty: 'hard', question: "What is a product roadmap?", options: ["A map showing the locations of retail outlets","A high-level plan of product direction, priorities and intended development over time","A record of every customer support ticket","A financial statement showing quarterly cash flow"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.productplan.com/glossary/product-roadmap/' },
  { id: 'bh035', category: 'business', difficulty: 'hard', question: "What is a stage-gate process in product development?", options: ["A method for setting employee salaries","A technique for calculating customer lifetime value","A sequence of development stages separated by decision points to review progress and continue, revise or stop","A system for processing online payments"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.stage-gate.com/blog/what-is-stage-gate/' },
  { id: 'bh036', category: 'business', difficulty: 'hard', question: "What is a critical path in project management?", options: ["The list of all project stakeholders","The shortest route between two company offices","A record of project expenses only","The sequence of dependent tasks that determines the minimum project duration"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.pmi.org/learning/library/critical-path-method-7036' },
  { id: 'bh037', category: 'business', difficulty: 'hard', question: "What is the purpose of a RACI matrix?", options: ["Clarify who is responsible, accountable, consulted and informed for project activities","Calculate the return on an advertising campaign","Compare suppliers' delivery costs","Measure employee satisfaction across departments"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.pmi.org/learning/library/raci-matrix-responsibility-assignment-briefing-10191' },
  { id: 'bh038', category: 'business', difficulty: 'hard', question: "What does the theory of constraints focus on?", options: ["Increasing every department's output independently","Identifying and managing the system's limiting constraint to improve overall performance","Reducing product quality to lower costs","Replacing forecasts with historical averages"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.toc-goldratt.com/en/theory-of-constraints' },
  { id: 'bh039', category: 'business', difficulty: 'hard', question: "What is a bottleneck in an operating process?", options: ["A task that always adds the most value","A product that has the highest selling price","A step whose limited capacity restricts the throughput of the whole process","A supplier that offers the largest discount"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.ibm.com/think/topics/bottleneck' },
  { id: 'bh040', category: 'business', difficulty: 'hard', question: "What is the purpose of a service blueprint?", options: ["Estimate the tax owed by a service business","Show the physical location of all service branches","Calculate the lifetime value of a customer","Map customer actions alongside frontstage and backstage service processes"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.nngroup.com/articles/service-blueprints-definition/' },
  { id: 'bh041', category: 'business', difficulty: 'hard', question: "What is a balanced scorecard designed to do?", options: ["Translate strategy into performance measures across financial and non-financial perspectives","Replace all financial statements with customer surveys","Measure only the market price of company shares","Track only employee attendance"], answer: 0, reviewedAt: '2026-11-06', source: 'https://balancedscorecard.org/bsc-basics-overview/' },
  { id: 'bh042', category: 'business', difficulty: 'hard', question: "What is scenario planning?", options: ["Choosing a single forecast and treating it as certain","Exploring multiple plausible future conditions to prepare strategic responses","Recording only the company's historical sales","Setting a fixed price for every future product"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.shell.com/what-we-do/scenarios.html' },
  { id: 'bh043', category: 'business', difficulty: 'hard', question: "What is risk appetite?", options: ["The total number of risks listed in a register","The amount of insurance premium paid each year","The level and type of risk an organisation is willing to accept in pursuit of its objectives","The probability that a customer will request a refund"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.coso.org/Pages/erm.aspx' },
  { id: 'bh044', category: 'business', difficulty: 'hard', question: "What is a sensitivity analysis used to examine?", options: ["The emotional response of customers to an advert","The number of employees required for a project","Whether a business has registered its intellectual property","How changes in key assumptions affect a model's outputs"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/s/sensitivityanalysis.asp' },
  { id: 'bh045', category: 'business', difficulty: 'hard', question: "What is the purpose of a covenant in a loan agreement?", options: ["Set conditions or restrictions the borrower agrees to observe","Guarantee that the lender will forgive the debt","Transfer ownership of the borrower's brand","Determine the retail price of the borrower's products"], answer: 0, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/c/covenant.asp' },
  { id: 'bh046', category: 'business', difficulty: 'hard', question: "What is a convertible note in startup financing?", options: ["A grant that never needs to be repaid or converted","A debt instrument that may convert into equity under specified terms","A share certificate that cannot be transferred","A short-term customer invoice"], answer: 1, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/c/convertible-note.asp' },
  { id: 'bh047', category: 'business', difficulty: 'hard', question: "What is a liquidation preference in venture financing?", options: ["A guarantee that founders receive a salary increase","A rule requiring a startup to pay no taxes","A term giving certain investors priority in receiving proceeds in a liquidation or sale","A clause preventing a company from issuing shares"], answer: 2, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/l/liquidation-preference.asp' },
  { id: 'bh048', category: 'business', difficulty: 'hard', question: "What does a term such as 'burn rate' describe for a startup?", options: ["The percentage of customers who cancel subscriptions","The number of products removed from inventory","The rate at which a company increases its retail prices","The rate at which it spends cash over a period"], answer: 3, reviewedAt: '2026-11-06', source: 'https://www.investopedia.com/terms/b/burnrate.asp' }
